const RED='#B3261E',REDD='#2A0A0C',REDC='#FFDAD6',GREEN='#1E6B3A',GREENC='#E8F5E9';
const MAYHELP=`Crash alerts may help, but they can miss a crash or go off when nothing happened. OpenBeacon never contacts emergency services. It doesn't replace calling 999.`;
const statusW=`<div class="status" style="color:#fff"><span>18:04</span><span>▼◢ ▮</span></div>`;
const statusNo=(c='#fff')=>`<div class="status" style="color:${c}"><span>18:06</span><span style="display:flex;gap:6px;align-items:center">${ic('wifi-off',15,c)} No signal ▮</span></div>`;
const big=(t,{bg='#fff',fg=RED,h=72,fs=22,b='',icon=''}={})=>`<div style="height:${h}px;border-radius:${h/2}px;background:${bg};color:${fg};display:flex;align-items:center;justify-content:center;gap:10px;font-size:${fs}px;font-weight:600;${b}">${icon?ic(icon,fs+2,fg):''}${t}</div>`;
const ring=(n,frac,s=220,c='#fff',track='rgba(255,255,255,.25)',fs=88)=>{const r=s/2-10,C=2*Math.PI*r;return `<div style="position:relative;width:${s}px;height:${s}px;margin:0 auto"><svg width="${s}" height="${s}" style="transform:rotate(-90deg)"><circle cx="${s/2}" cy="${s/2}" r="${r}" stroke="${track}" stroke-width="7" fill="none"/><circle cx="${s/2}" cy="${s/2}" r="${r}" stroke="${c}" stroke-width="7" fill="none" stroke-linecap="round" stroke-dasharray="${C*frac} ${C}"/></svg><div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:${c}"><div style="font-size:${fs}px;font-weight:700;line-height:1;font-variant-numeric:tabular-nums;letter-spacing:-4px">${n}</div><div style="font-size:15px;opacity:.85;margin-top:4px">seconds</div></div></div>`;};
const pinAt=(x,y,t='Sa',c='#E6005C')=>`<div style="position:absolute;left:${x-24}px;top:${y-24}px;width:48px;height:48px;border-radius:24px;background:${c};border:3px solid #fff;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:600;box-shadow:0 2px 6px rgba(0,0,0,.3);z-index:3">${t}</div>`;
const crashAt=(x,y)=>`<div style="position:absolute;left:${x-20}px;top:${y-20}px;width:40px;height:40px;border-radius:12px;background:${RED};border:3px solid #fff;color:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.3);transform:rotate(45deg);z-index:2"><div style="transform:rotate(-45deg);display:flex">${ic('triangle-alert',18,'#fff',2.4)}</div></div>`;
const plainMap=`<div class="mapw"></div>`;
const mapTop=`<div class="topbar" style="justify-content:space-between"><div class="gchip"><i></i>Family${ic('chevron-down',18)}</div><div class="nb">${ic('users',20)}</div></div>`;
const btnRow=(a)=>`<div class="row" style="gap:8px;margin-top:12px">${a}</div>`;
const updBtns=`<div class="btn tonal" style="flex:1">${ic('refresh-cw',18)}Update now</div><div class="btn tonal" style="flex:1">${ic('navigation',18)}Directions</div>`;
const personHead=(sub=`<span style="color:#2E7D32;font-weight:500">Updating live</span> · 20 s ago`)=>`<div class="row">${av('Sa',48)}<div class="sp"><div style="font-size:21px;font-weight:700">Sam</div><div style="font-size:14px" class="muted">${sub}</div></div><span class="tag grey">${ic('gauge',13)}0 mph</span></div>`;
const shadeBg=`background:linear-gradient(160deg,#3b2a33,#1d1a24)`;
const notif=({app='OpenBeacon',when='now',icon='siren',ic1=RED,title,body,acts='',ch='',dim=false})=>`<div style="background:${dim?'#2c2a31':'#f3edf0'};color:${dim?'#eee':'#1d1b20'};border-radius:24px;padding:14px 16px;margin:0 12px 8px"><div class="row" style="gap:8px;font-size:12.5px;${dim?'color:#bbb':'color:#49454f'}"><div style="width:22px;height:22px;border-radius:11px;background:${ic1};display:flex;align-items:center;justify-content:center">${ic(icon,13,'#fff',2.4)}</div>${app}${ch?` · ${ch}`:''} · ${when}</div><div style="font-size:15.5px;font-weight:600;margin-top:8px">${title}</div><div style="font-size:14px;margin-top:2px;line-height:1.38;${dim?'color:#ccc':'color:#49454f'}">${body}</div>${acts?`<div class="row" style="gap:18px;margin-top:10px;font-size:14px;font-weight:600;color:${dim?'#f2b8c6':'var(--p)'}">${acts}</div>`:''}</div>`;
const lock=(inner,time='18:05')=>phone(`<div class="status" style="color:#fff"><span></span><span>▼◢ ▮</span></div><div style="text-align:center;color:#fff;font-size:64px;font-weight:300;margin:30px 0 4px">${time}</div><div style="text-align:center;color:#ddd;font-size:15px;margin-bottom:26px">Tuesday 24 November</div>${inner}`,shadeBg);
const settingRow=(t,s,on,icon,dis=false)=>`<div class="item" style="${dis?'opacity:.5':''}"><div class="ic">${ic(icon,20)}</div><div class="t">${t}${s?`<small>${s}</small>`:''}</div>${on==null?'':`<div style="width:52px;height:32px;border-radius:16px;background:${on?'var(--p)':'var(--sch)'};border:2px solid ${on?'var(--p)':'var(--ol)'};position:relative;flex:none"><div style="position:absolute;top:${on?3:6}px;${on?'right:3px':'left:6px'};width:${on?22:16}px;height:${on?22:16}px;border-radius:11px;background:${on?'#fff':'var(--ol)'}"></div></div>`}</div>`;
const screen=(title,body)=>phone(status+`<div class="row" style="padding:8px 16px 4px;gap:10px"><div class="nb" style="background:transparent">${ic('chevron-left',24)}</div><div style="font-size:22px">${title}</div></div>`+body);
